import { TEAMS_BOT_ID_PREFIX } from "./activity.js";
const HOUR_MS = 60 * 60 * 1000;
const IDLE_RESET_MS = 24 * HOUR_MS;
const DEFAULT_BOT_WAKES_PER_HOUR = 5;
const DEFAULT_BOT_WAKES_TOTAL = 20;
export function assertTeamsEngagement(engagement) {
    const posts = engagement?.channelPosts;
    if (posts !== undefined) {
        if (posts.allow.length === 0) {
            throw new Error('teamsChannel engagement.channelPosts.allow must name a channel or be ["*"]');
        }
        if (posts.allow.includes("*") && posts.allow.length > 1) {
            throw new Error('teamsChannel engagement.channelPosts.allow cannot mix "*" with channel ids');
        }
        const bad = posts.allow.find((id) => id !== "*" && !id.startsWith("19:"));
        if (bad !== undefined) {
            throw new Error(`teamsChannel engagement.channelPosts.allow entry ${JSON.stringify(bad)} is not a Teams channel id (19:…)`);
        }
    }
    if (engagement?.botMentions !== undefined && engagement.botMentions.allowFrom.length === 0) {
        throw new Error("teamsChannel engagement.botMentions.allowFrom must name at least one bot");
    }
}
export function needsThreadSessionCheck(message, engagement) {
    return message.isReply && !message.mentionsBot && engagement?.channelPosts?.replies === "joined";
}
export function gateTeamsMessage(input) {
    const { message, engagement } = input;
    if (message.author.id === input.botId) {
        return { kind: "drop", reason: "own_post" };
    }
    if (message.conversation.type === "personal") {
        if (message.author.isBot) {
            return { kind: "drop", reason: "bot_author" };
        }
        return engagement?.directMessages === false
            ? { kind: "drop", reason: "direct_messages_off" }
            : { kind: "dispatch", engagement: "directMessage", botWake: false };
    }
    if (message.mentionsBot && engagement?.mentions !== false) {
        if (!message.author.isBot) {
            return { kind: "dispatch", engagement: "mention", botWake: false };
        }
        return botMentionAllowed(message.author.id, engagement?.botMentions)
            ? { kind: "dispatch", engagement: "mention", botWake: true }
            : { kind: "drop", reason: "bot_mention_not_allowed" };
    }
    const posts = engagement?.channelPosts;
    if (message.conversation.type !== "channel" || posts === undefined) {
        return { kind: "drop", reason: "not_mentioned" };
    }
    if (message.author.isBot && posts.includeBotPosts !== true) {
        return { kind: "drop", reason: "bot_post" };
    }
    return watchesPost(message, posts, input.threadHasSession)
        ? { kind: "dispatch", engagement: "channelPost", botWake: message.author.isBot }
        : { kind: "drop", reason: "not_watched" };
}
function watchesPost(message, posts, threadHasSession) {
    const allowlisted = posts.allow.includes("*") || posts.allow.includes(message.conversation.id);
    const which = posts.posts ?? "top-level";
    if (!message.isReply) {
        return allowlisted && which !== "replies";
    }
    return (allowlisted && which !== "top-level") || (posts.replies === "joined" && threadHasSession);
}
function botMentionAllowed(authorId, options) {
    if (options === undefined) {
        return false;
    }
    // Bot ids are app GUIDs, which Teams and Azure send in either letter case.
    const author = authorId.toLowerCase();
    return options.allowFrom.some((entry) => {
        const id = entry.toLowerCase();
        return id === author || `${TEAMS_BOT_ID_PREFIX}${id}` === author;
    });
}
/**
 * Wakes per thread. A thread idle for 24 hours starts over, so its entry is
 * evicted then.
 */
export function createBotWakeBudget(options, now = Date.now) {
    const perHour = options?.maxPerThreadPerHour ?? DEFAULT_BOT_WAKES_PER_HOUR;
    const total = options?.maxPerThreadTotal ?? DEFAULT_BOT_WAKES_TOTAL;
    const wakes = new Map();
    const evictIdle = (at) => {
        for (const [key, history] of wakes) {
            const last = history.at(-1);
            if (last === undefined || at - last >= IDLE_RESET_MS) {
                wakes.delete(key);
            }
        }
    };
    return {
        tryWake(threadKey) {
            const at = now();
            evictIdle(at);
            const history = wakes.get(threadKey) ?? [];
            const lastHour = history.filter((time) => at - time < HOUR_MS).length;
            if (lastHour >= perHour || history.length >= total) {
                return false;
            }
            wakes.delete(threadKey);
            wakes.set(threadKey, [...history, at]);
            return true;
        },
        release(threadKey) {
            const history = wakes.get(threadKey);
            if (history === undefined) {
                return;
            }
            if (history.length <= 1) {
                wakes.delete(threadKey);
                return;
            }
            wakes.set(threadKey, history.slice(0, -1));
        },
        size: () => wakes.size,
    };
}
